
from myscelium import MysceliumClient, ClientPatterns, callback_pattern, ClientPattern, HostPatterns
import os
import time
import signal

client_patterns = ClientPatterns()

CLIENT_KEY = "some_client_id"

# Theoricaly, we have some restrictions to cast command 
# they need to follow some rules, this rules are related to the
# targets, targets have some rules, for example, we should not 
# send a response generated by target X to target X for example,
# this kind of thing should generate a error previously
# we should not be able to mess with the targets in a way that it can cause conflicts

command = client_patterns.command_pattern(
    origin_key=CLIENT_KEY,
    command_function="python_function",
    target_key=CLIENT_KEY,  # Empty is default
    kwargs={"age": 10, "birth": 8, "name": "cristian"},
    message="",
    response_type="ExternalFunction",
    # response_target=f"ClientKey({CLIENT_KEY})", Should give an error
    response_target="Origin",
    response_actf="test_handler",
    auto_collect_response=True,
)

# What the base struct should looks like:
base = {
    'mode': 'Function', 
    'type': 'ExternalFunction', 
    'target': 'Host', 
    'status': 'Success', 
    'origin': 'ClientKey(some_client_id)', 
    'actf': 'python_function', 
    'kwargs': {
        'age': 10, 
        'birth': 8, 
        'name': 'cristian'
    }, 
    'message': '', 
    'response_type': 'ExternalFunction', 
    'response_target': 'Origin', 
    'response_actf': 'test_handler', 
    'collect_response': True
}


print(ClientPattern(
    client_name="TestClient1", 
    client_type="Interface", 
    client_key="some_client_id", 
    client_permission_group="", 
    client_is_super_user=True, 
    max_sub_channels=5
).format())

print(HostPatterns().client_pattern(
    client_name="TestClient1", 
    client_type="Interface", 
    client_key="some_client_id", 
    client_permission_group="", 
    client_is_super_user=True, 
    max_sub_channels=5
))

